package com.kgsat.payment.consumer; import com.kgsat.payment.model.*; import com.kgsat.payment.producer.PaymentProducer; import com.kgsat.payment.repository.ProcessedOrderRepository; import org.slf4j.*; import org.springframework.kafka.annotation.*; import org.springframework.kafka.retrytopic.*; import org.springframework.kafka.support.Acknowledgment; import org.springframework.stereotype.Component; import java.time.Instant; import java.util.UUID;
@Component public class PaymentConsumer { private static final Logger log=LoggerFactory.getLogger(PaymentConsumer.class); private final ProcessedOrderRepository repository; private final PaymentProducer producer; public PaymentConsumer(ProcessedOrderRepository r,PaymentProducer p){repository=r;producer=p;} @RetryableTopic(attempts="3",dltTopicSuffix="-dlt",autoCreateTopics="true") @KafkaListener(topics="${app.kafka.orders-topic}",groupId="payment-service") public void consume(OrderEvent order,Acknowledgment ack){if(!repository.claim(order.orderId())){log.info("event=duplicate_ignored orderId={}",order.orderId());ack.acknowledge();return;} try{log.info("event=payment_started orderId={}",order.orderId());if(order.simulateFailure()) throw new IllegalStateException("simulated payment failure");producer.send(new PaymentEvent(UUID.randomUUID().toString(),order.orderId(),order.customerId(),order.amount(),"SUCCESS",Instant.now()));log.info("event=payment_success orderId={}",order.orderId());ack.acknowledge();}catch(RuntimeException e){repository.release(order.orderId());log.warn("event=retry_attempt orderId={} reason={}",order.orderId(),e.getMessage());throw e;}} @KafkaListener(topics="orders-dlt",groupId="payment-dlt-monitor") public void dlt(Object message){log.error("event=dlq_published topic=orders-dlt payload={}",message);} }
